#!/usr/bin/env node
/**
 * record-costclaw-demo.mjs - records a CostClaw audit walkthrough for ProductDemo.
 *
 * CostClaw is a CLI product, so there is no app to point a browser at. The two
 * surfaces a real `costclaw audit` run produces are filmed instead:
 *   1. the colored terminal report, replayed from the product's REAL ANSI bytes
 *      (ansi-replay.mjs converts them to styled spans in the report's own palette)
 *   2. the self-contained HTML report the same run writes to disk
 * Both come from evidence generated by the product's own pipeline
 * (costclaw-audit-evidence.mts). Nothing on screen is mocked.
 *
 * Prereq: the audit evidence on disk (this run reuses it; it is not regenerated,
 * because the audit reads live logs and every re-run changes the numbers):
 *   out/costclaw/marketing/demo/{terminal-after.txt,html-after.html}   (preferred)
 *   out/costclaw/marketing/polish/{terminal-after.txt,html-after.html} (fallback)
 *
 * Output: ../../studio/public/costclaw/demo.webm + ../../props/costclaw-demo.json
 *
 * Camera focus rects are MEASURED from each target element's real boundingBox
 * (viewport px == webm px because recordVideo.size == viewport), never derived
 * from click points. There are no clicks: a CLI demo has no cursor to fake.
 */
import {chromium} from '@playwright/test';
import {createHash} from 'node:crypto';
import {copyFileSync, existsSync, mkdirSync, readFileSync, writeFileSync} from 'node:fs';
import {dirname, join, resolve} from 'node:path';
import {pathToFileURL, fileURLToPath} from 'node:url';
import {Recorder} from './recorder.mjs';
import {replayHtml, resolveGroups, toLines} from './ansi-replay.mjs';
import {cacheKey, checkCache, storeCache} from '../../scripts/lib/cache.mjs';
import {captureKeyParts} from './capture-cache.mjs';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');
const CC_ROOT = process.env.CC_ROOT ?? 'C:/Projects/costclaw';
const VIEWPORT = {width: 1440, height: 900};
const SETTLE_MS = 650; // let reveal/scroll settle before measuring a focus rect

// Replay pacing: the command types, then the real output streams line by line.
const REPLAY = {command: 'npx costclaw audit', typeMs: 58, lineMs: 30, blankMs: 130};

// Camera focus groups in the terminal replay, resolved from report content markers.
const TERMINAL_GROUPS = [
  {id: 'beat-headline', start: 'Recoverable usage', endBefore: 'Plan:'},
  {id: 'beat-score', start: 'Overall setup score', endBefore: 'Top fixes'},
  {id: 'beat-fixes', start: 'Top fixes by recoverable spend', endBefore: 'Other issues to tighten'},
];

// --- Evidence resolution (before the cache gate: its bytes are a cache input) ---
const EVIDENCE_DIRS = [
  join(ROOT, 'out', 'costclaw', 'marketing', 'demo'),
  join(ROOT, 'out', 'costclaw', 'marketing', 'polish'),
];
const evidenceDir = EVIDENCE_DIRS.find(
  (d) => existsSync(join(d, 'terminal-after.txt')) && existsSync(join(d, 'html-after.html')),
);
if (!evidenceDir) {
  console.error(
    'Audit evidence not found. Generate it from the product repo:\n' +
      `  cd ${CC_ROOT.replace(/\//g, '\\')}\n` +
      `  npx tsx ${join(ROOT, 'feeders', 'capture', 'costclaw-audit-evidence.mts')} ${EVIDENCE_DIRS[0]}`,
  );
  process.exit(1);
}
const ansiText = readFileSync(join(evidenceDir, 'terminal-after.txt'), 'utf8');
const reportHtml = readFileSync(join(evidenceDir, 'html-after.html'), 'utf8');

// --- Footage cache gate (before the browser launch) ---
const argv = process.argv.slice(2);
const FORCE = argv.includes('--force');
const CHECK_ONLY = argv.includes('--cache-check-only');
const videoOut = join(ROOT, 'studio', 'public', 'costclaw', 'demo.webm');
const propsOut = join(ROOT, 'props', 'costclaw-demo.json');
const CACHE_ARTIFACTS = [videoOut, propsOut];
const sha = (s) => createHash('sha256').update(s).digest('hex');
const keyParts = captureKeyParts({
  repo: CC_ROOT,
  scriptPath: fileURLToPath(import.meta.url),
  config: {
    viewport: VIEWPORT,
    settleMs: SETTLE_MS,
    replay: REPLAY,
    // captureKeyParts hashes THIS script only; the replay page it films is built
    // by a sibling module, so its source has to be in the key too.
    replayModule: sha(readFileSync(join(ROOT, 'feeders', 'capture', 'ansi-replay.mjs'), 'utf8')),
    // The filmed evidence is a real input: different numbers, different footage.
    evidence: {terminal: sha(ansiText), report: sha(reportHtml)},
  },
});
const CACHE_KEY = cacheKey(keyParts);
const CACHE_ENABLED = keyParts.productHead !== null; // null => product state unverifiable

if (CHECK_ONLY) {
  const {hit} = CACHE_ENABLED ? checkCache('costclaw', 'capture', CACHE_KEY, CACHE_ARTIFACTS) : {hit: false};
  console.log(hit ? 'HIT' : 'MISS');
  process.exit(0);
}
if (!CACHE_ENABLED) {
  console.log(`capture cache: product git state unavailable at ${CC_ROOT} — caching disabled this run`);
} else if (!FORCE) {
  const {hit} = checkCache('costclaw', 'capture', CACHE_KEY, CACHE_ARTIFACTS);
  if (hit) {
    console.log(`capture cache hit — reusing ${videoOut}`);
    process.exit(0);
  }
}

// --- Build the two pages this take films ---
const stageDir = join(ROOT, 'out', 'capture', 'costclaw');
mkdirSync(stageDir, {recursive: true});
const groups = resolveGroups(toLines(ansiText), TERMINAL_GROUPS);
const replayPage = join(stageDir, 'terminal.html');
const reportPage = join(stageDir, 'report.html');
writeFileSync(replayPage, replayHtml({ansiText, groups, ...REPLAY}));
writeFileSync(reportPage, reportHtml);

const clampFocus = (box, {padX = 48, padY = 48} = {}) => {
  const w = Math.min(VIEWPORT.width, box.width + padX * 2);
  const h = Math.min(VIEWPORT.height, box.height + padY * 2);
  const x = Math.min(Math.max(box.x + box.width / 2, w / 2), VIEWPORT.width - w / 2);
  const y = Math.min(Math.max(box.y + box.height / 2, h / 2), VIEWPORT.height - h / 2);
  return {x: Math.round(x), y: Math.round(y), w: Math.round(w), h: Math.round(h)};
};

const videoDir = join(ROOT, 'out', 'capture');
let browser;
try {
  browser = await chromium.launch();
  const context = await browser.newContext({
    viewport: VIEWPORT,
    deviceScaleFactor: 2, // supersampled render downscaled into the webm: crisper footage
    recordVideo: {dir: videoDir, size: VIEWPORT},
  });
  const page = await context.newPage();
  const rec = new Recorder();

  // Centers one MEASURED element, after scrolling it into view and settling.
  // biasX pulls a narrow, left-aligned block back toward the terminal card's
  // middle, so a max-zoom shot does not fill a quarter of the frame with margin.
  const focusOn = async (selector, {padX, padY, biasX = 0, biasY = 0} = {}) => {
    const loc = page.locator(selector).first();
    await loc.evaluate((el) => el.scrollIntoView({block: 'center'}));
    await page.waitForTimeout(SETTLE_MS);
    const box = await loc.boundingBox();
    if (!box) throw new Error(`focus target ${selector} has no bounding box`);
    const f = clampFocus(box, {padX, padY});
    f.x = Math.min(Math.max(f.x + biasX, f.w / 2), VIEWPORT.width - f.w / 2);
    f.y = Math.min(Math.max(f.y + biasY, f.h / 2), VIEWPORT.height - f.h / 2);
    rec.focusAt(f.x, f.y, {w: f.w, h: f.h});
  };

  // --- Act 1: the terminal report ---
  await page.goto(pathToFileURL(replayPage).href, {waitUntil: 'load'});
  rec.start();
  rec.step('One free command reads the session logs on your machine.');
  // Wide, no focus: the command types itself and the real output streams in.
  await page.waitForFunction(() => window.__replayDone === true, null, {timeout: 30_000});
  await page.waitForTimeout(500);

  rec.step('Recoverable usage, priced from real token counts.');
  await focusOn('#beat-headline', {padX: 44, padY: 70});
  await page.waitForTimeout(3400);

  rec.step('Six setup pillars, scored from evidence only.');
  await focusOn('#beat-score', {padX: 60, padY: 60, biasX: 130});
  await page.waitForTimeout(3400);

  rec.step('Fixes ranked by the dollars each one returns.');
  await focusOn('#beat-fixes', {padX: 44, padY: 44});
  await page.waitForTimeout(3600);

  // --- Act 2: the HTML report the same run writes ---
  await page.goto(pathToFileURL(reportPage).href, {waitUntil: 'load'});
  rec.step('The same run writes a local HTML report.');
  await focusOn('.banner', {padX: 110, padY: 90});
  await page.waitForTimeout(3300);

  rec.step('Spend by project, read from your own logs.');
  await focusOn('.chart', {padX: 50, padY: 50});
  await page.waitForTimeout(3300);

  rec.step('Every fix carries the evidence behind it.');
  await focusOn('ul.fixes .fix', {padX: 40, padY: 40});
  await page.waitForTimeout(3400);

  const telemetry = rec.finish(VIEWPORT);
  const video = page.video();
  await context.close(); // flushes the webm
  const src = await video.path();

  const destDir = join(ROOT, 'studio', 'public', 'costclaw');
  mkdirSync(destDir, {recursive: true});
  copyFileSync(src, join(destDir, 'demo.webm'));

  const props = {
    brandId: 'costclaw',
    video: 'costclaw/demo.webm',
    cta: 'Run the free audit: npx costclaw audit',
    telemetry,
  };
  writeFileSync(propsOut, JSON.stringify(props, null, 2) + '\n');
  if (CACHE_ENABLED) {
    storeCache('costclaw', 'capture', CACHE_KEY, CACHE_ARTIFACTS, {
      productRepo: CC_ROOT,
      productHead: keyParts.productHead,
      evidenceDir,
    });
  }
  console.log(`capture OK: ${telemetry.durationMs}ms, ${telemetry.events.length} events`);
  console.log(`evidence: ${evidenceDir}`);
  console.log('wrote studio/public/costclaw/demo.webm and props/costclaw-demo.json');
} catch (err) {
  console.error(String(err?.stack ?? err?.message ?? err));
  process.exitCode = 1;
} finally {
  if (browser) await browser.close();
}
